const input = $input.first().json;
const fromDate = String(input.fromDate || '').trim();
const toDate = String(input.toDate || '').trim();
const token = String(input.accessToken || '').trim();
const userId = String(input.threadsUserId || '').trim();
const datePattern = /^\d{4}-\d{2}-\d{2}$/;
if (!datePattern.test(fromDate) || !datePattern.test(toDate)) throw new Error('fromDate and toDate must use YYYY-MM-DD format.');
if (!token || token === 'PASTE_THREADS_ACCESS_TOKEN_HERE') throw new Error('Enter a valid Threads access token in the Edit Fields — Inputs node.');
if (!/^\d+$/.test(userId)) throw new Error('threadsUserId must contain only digits.');
const from = new Date(fromDate + 'T00:00:00+06:00');
const until = new Date(toDate + 'T00:00:00+06:00');
until.setDate(until.getDate() + 1);
if (Number.isNaN(from.getTime()) || Number.isNaN(until.getTime()) || from >= until) throw new Error('The date range is invalid. Ensure fromDate is on or before toDate.');
const since = Math.floor(from.getTime() / 1000);
const untilExclusive = Math.floor(until.getTime() / 1000);
const insightBase = 'https://graph.threads.com/v1.0/' + encodeURIComponent(userId) + '/threads_insights';
const makeInsightUrl = (metric, breakdown) => { let url = insightBase + '?metric=' + encodeURIComponent(metric) + '&access_token=' + encodeURIComponent(token); if (breakdown) url += '&breakdown=' + encodeURIComponent(breakdown); else if (metric !== 'followers_count') url += '&since=' + since + '&until=' + untilExclusive; return url; };
const profileUrl = 'https://graph.threads.com/v1.0/' + encodeURIComponent(userId) + '?fields=id,username,name,threads_profile_picture_url,is_verified&access_token=' + encodeURIComponent(token);
const requests = [
  { requestType: 'dated_metrics', metric: 'views,likes,replies,reposts,quotes,clicks', requestUrl: makeInsightUrl('views,likes,replies,reposts,quotes,clicks', '') },
  { requestType: 'followers_count', metric: 'followers_count', requestUrl: makeInsightUrl('followers_count', '') },
  { requestType: 'follower_demographics_country', metric: 'follower_demographics', breakdown: 'country', requestUrl: makeInsightUrl('follower_demographics', 'country') },
  { requestType: 'follower_demographics_city', metric: 'follower_demographics', breakdown: 'city', requestUrl: makeInsightUrl('follower_demographics', 'city') },
  { requestType: 'follower_demographics_age', metric: 'follower_demographics', breakdown: 'age', requestUrl: makeInsightUrl('follower_demographics', 'age') },
  { requestType: 'follower_demographics_gender', metric: 'follower_demographics', breakdown: 'gender', requestUrl: makeInsightUrl('follower_demographics', 'gender') },
  { requestType: 'profile', requestUrl: profileUrl }
];
return requests.map(request => ({ json: { ...request, fromDate, toDate, timezone: 'GMT+6', since, untilExclusive, telegramChatId: input.telegramChatId } }));

const requests = $('Build Insights Requests').all();
const responses = $input.all();
const records = responses.map((item, index) => ({ request: requests[index]?.json || {}, response: item.json || {} }));
return [{ json: { apiTestStatus: 'completed', generatedAt: new Date().toISOString(), fromDate: requests[0]?.json?.fromDate || '', toDate: requests[0]?.json?.toDate || '', timezone: 'GMT+6', telegramChatId: requests[0]?.json?.telegramChatId || '', records } }];

const source = $input.first().json || {};
const records = Array.isArray(source.records) ? source.records : [];

const esc = value => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const bodyOf = record => record?.response?.body ?? record?.response ?? {};
const recordByType = type => records.find(record => record.request?.requestType === type) || {};
const dataOf = type => {
  const body = bodyOf(recordByType(type));
  return Array.isArray(body?.data) ? body.data : [];
};

const profile = bodyOf(recordByType('profile')) || {};
const accountName = profile.name || profile.username || 'Threads Account';
const username = profile.username ? '@' + String(profile.username).replace(/^@/, '') : '@unknown';
const avatar = profile.threads_profile_picture_url || '';
const initial = esc(String(accountName).charAt(0).toUpperCase() || 'T');
const number = value => Number(value || 0);
const formatNumber = value => number(value).toLocaleString('en-US');
const shortNumber = value => {
  const n = number(value);
  if (n >= 1000000) return (n / 1000000).toFixed(1).replace('.0', '') + 'M';
  if (n >= 1000) return (n / 1000).toFixed(1).replace('.0', '') + 'K';
  return formatNumber(n);
};

const datedSeries = dataOf('dated_metrics');
const metricSeries = metric => datedSeries.find(series => series?.name === metric) || {};
const metricTotal = metric => {
  const series = metricSeries(metric);
  if (Array.isArray(series.values)) return series.values.reduce((sum, point) => sum + number(point?.value), 0);
  if (series.total_value && typeof series.total_value.value !== 'undefined') return number(series.total_value.value);
  if (Array.isArray(series.link_total_values)) return series.link_total_values.reduce((sum, point) => sum + number(point?.value), 0);
  return 0;
};

const viewsSeries = Array.isArray(metricSeries('views').values)
  ? metricSeries('views').values.map(point => ({ date: point.end_time, value: number(point.value) }))
  : [];
const viewsTotal = viewsSeries.reduce((sum, point) => sum + point.value, 0);
const peakViews = viewsSeries.reduce((best, point) => point.value > best.value ? point : best, { value: 0, date: '' });
const followersData = dataOf('followers_count');
const followersSeries = followersData.find(series => series?.name === 'followers_count') || followersData[0] || {};
const followers = number(followersSeries?.total_value?.value ?? followersSeries?.value ?? 0);

const demographics = type => {
  const series = dataOf(type)[0] || {};
  const breakdown = series?.total_value?.breakdowns?.[0];
  const results = Array.isArray(breakdown?.results) ? breakdown.results : [];
  return results.map(result => ({
    label: Array.isArray(result.dimension_values) ? result.dimension_values.join(' / ') : 'Unknown',
    value: number(result.value)
  })).filter(item => item.value > 0).sort((a, b) => b.value - a.value).slice(0, 10);
};

const formatDateLabel = value => {
  if (!value) return '';
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? String(value).slice(0, 10) : date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
};

const svgLineChart = points => {
  if (!points.length) return '<div class="empty">No daily views data returned.</div>';
  const width = 960;
  const height = 280;
  const pad = { left: 58, right: 24, top: 24, bottom: 46 };
  const max = Math.max(...points.map(point => point.value), 1);
  const x = index => pad.left + (points.length === 1 ? 0 : index * (width - pad.left - pad.right) / (points.length - 1));
  const y = value => height - pad.bottom - (value / max) * (height - pad.top - pad.bottom);
  const coords = points.map((point, index) => `${x(index).toFixed(1)},${y(point.value).toFixed(1)}`);
  const dots = points.map((point, index) => `<circle cx="${x(index).toFixed(1)}" cy="${y(point.value).toFixed(1)}" r="3.5" fill="#2563eb"><title>${esc(formatDateLabel(point.date))}: ${esc(formatNumber(point.value))} views</title></circle>`).join('');
  const grid = [0, .25, .5, .75, 1].map(ratio => {
    const yy = y(max * ratio).toFixed(1);
    return `<line x1="${pad.left}" y1="${yy}" x2="${width - pad.right}" y2="${yy}" stroke="#e2e8f0" stroke-width="1"/><text x="${pad.left - 10}" y="${Number(yy) + 4}" text-anchor="end" class="axis">${esc(shortNumber(max * ratio))}</text>`;
  }).join('');
  const labels = [0, Math.floor((points.length - 1) / 2), points.length - 1].filter((value, index, arr) => arr.indexOf(value) === index).map(index => `<text x="${x(index).toFixed(1)}" y="${height - 14}" text-anchor="middle" class="axis">${esc(formatDateLabel(points[index].date))}</text>`).join('');
  return `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Daily views trend" class="line-chart">${grid}<polyline points="${coords.join(' ')}" fill="none" stroke="#2563eb" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>${dots}${labels}</svg>`;
};

const barChart = (items, emptyText) => {
  if (!items.length) return `<div class="empty">${esc(emptyText)}</div>`;
  const max = Math.max(...items.map(item => item.value), 1);
  return `<div class="bars">${items.map(item => {
    const percent = Math.max(3, Math.round(item.value / max * 100));
    return `<div class="bar-row"><div class="bar-label" title="${esc(item.label)}">${esc(item.label)}</div><div class="bar-track"><div class="bar-fill" style="width:${percent}%"></div></div><div class="bar-value">${esc(formatNumber(item.value))}</div></div>`;
  }).join('')}</div>`;
};

const countryData = demographics('follower_demographics_country');
const cityData = demographics('follower_demographics_city');
const genderData = demographics('follower_demographics_gender');
const metrics = [
  ['Views', viewsTotal, 'blue'],
  ['Likes', metricTotal('likes'), 'pink'],
  ['Replies', metricTotal('replies'), 'purple'],
  ['Reposts', metricTotal('reposts'), 'green'],
  ['Quotes', metricTotal('quotes'), 'orange'],
  ['Clicks', metricTotal('clicks'), 'teal'],
  ['Followers', followers, 'navy']
];
const cards = metrics.map(([label, value, color]) => `<div class="metric-card ${color}"><div class="metric-label">${esc(label)}</div><div class="metric-value">${esc(formatNumber(value))}</div><div class="metric-accent"></div></div>`).join('');
const avatarHtml = avatar ? `<img class="avatar" src="${esc(avatar)}" alt="${esc(accountName)} profile photo">` : `<div class="avatar fallback">${initial}</div>`;
const generatedAt = new Date(source.generatedAt || Date.now()).toLocaleString('en-US', { dateStyle: 'medium', timeStyle: 'short' });
const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Threads Insights Report — ${esc(accountName)}</title>
<style>
:root{--ink:#122033;--muted:#64748b;--line:#e2e8f0;--panel:#fff;--bg:#eef3f8;--blue:#2563eb}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,Segoe UI,Arial,sans-serif}.page{max-width:1180px;margin:0 auto;background:#fff;min-height:100vh}.hero{padding:42px 54px 48px;color:#fff;background:radial-gradient(circle at 85% 5%,rgba(96,165,250,.55),transparent 32%),linear-gradient(135deg,#0f172a 0%,#1d4ed8 100%)}.eyebrow{font-size:12px;letter-spacing:2px;text-transform:uppercase;opacity:.75;font-weight:700}.identity{display:flex;align-items:center;gap:20px;margin-top:22px}.avatar{width:92px;height:92px;border-radius:50%;object-fit:cover;border:4px solid rgba(255,255,255,.9);background:#60a5fa}.fallback{display:flex;align-items:center;justify-content:center;font-size:40px;font-weight:800}.name{font-size:34px;font-weight:800;letter-spacing:-.5px}.handle{font-size:16px;opacity:.8;margin-top:5px}.hero-meta{margin-top:34px;display:flex;gap:24px;flex-wrap:wrap;color:#dbeafe;font-size:14px}.content{padding:38px 54px 52px}.section-title{font-size:22px;margin:0 0 7px;letter-spacing:-.2px}.section-subtitle{color:var(--muted);font-size:14px;margin:0 0 22px}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:22px 0 40px}.metric-card{position:relative;overflow:hidden;border:1px solid var(--line);border-radius:16px;padding:19px;background:var(--panel);box-shadow:0 7px 20px rgba(15,23,42,.05)}.metric-label{font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:1.1px;font-weight:700}.metric-value{font-size:30px;font-weight:800;margin-top:10px;letter-spacing:-.8px}.metric-accent{position:absolute;left:0;bottom:0;height:4px;width:100%;background:var(--blue)}.pink .metric-accent{background:#ec4899}.purple .metric-accent{background:#8b5cf6}.green .metric-accent{background:#10b981}.orange .metric-accent{background:#f59e0b}.teal .metric-accent{background:#14b8a6}.navy .metric-accent{background:#334155}.chart-card{border:1px solid var(--line);border-radius:18px;padding:24px;background:#fff;box-shadow:0 8px 24px rgba(15,23,42,.05);margin-bottom:26px}.chart-head{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:16px}.chart-title{font-size:18px;font-weight:800}.chart-note{font-size:13px;color:var(--muted);margin-top:5px}.highlight{font-size:14px;color:#1d4ed8;font-weight:700;white-space:nowrap}.line-chart{display:block;width:100%;height:auto;min-height:250px}.axis{font-size:12px;fill:#64748b}.demographics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.bars{margin-top:12px}.bar-row{display:grid;grid-template-columns:180px 1fr 72px;align-items:center;gap:10px;margin:13px 0}.bar-label{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#334155;font-size:13px}.bar-track{height:11px;background:#e8eef6;border-radius:999px;overflow:hidden}.bar-fill{height:100%;border-radius:999px;background:linear-gradient(90deg,#2563eb,#60a5fa)}.bar-value{text-align:right;color:#0f172a;font-size:13px;font-weight:700}.empty{padding:28px;text-align:center;color:var(--muted);background:#f8fafc;border-radius:12px}.footer{border-top:1px solid var(--line);padding:24px 54px;color:var(--muted);font-size:12px;line-height:1.6}@media(max-width:850px){.content,.hero,.footer{padding-left:24px;padding-right:24px}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.demographics{grid-template-columns:1fr}.bar-row{grid-template-columns:135px 1fr 62px}}@media(max-width:520px){.metrics{grid-template-columns:1fr 1fr}.metric-value{font-size:23px}.name{font-size:26px}.bar-row{grid-template-columns:105px 1fr 55px}}
</style></head><body><div class="page"><header class="hero"><div class="eyebrow">Threads Insights Report</div><div class="identity">${avatarHtml}<div><div class="name">${esc(accountName)}</div><div class="handle">${esc(username)}</div></div></div><div class="hero-meta"><span>Reporting period: <strong>${esc(source.fromDate)} – ${esc(source.toDate)}</strong></span><span>Timezone: <strong>${esc(source.timezone || 'GMT+6')}</strong></span><span>Generated: <strong>${esc(generatedAt)}</strong></span></div></header><main class="content"><h1 class="section-title">Performance Summary</h1><p class="section-subtitle">Aggregated Threads account activity for the selected date range.</p><div class="metrics">${cards}</div><div class="chart-card"><div class="chart-head"><div><div class="chart-title">Daily Views Trend</div><div class="chart-note">Views recorded by day across the reporting period.</div></div><div class="highlight">Peak: ${esc(formatNumber(peakViews.value))} views</div></div>${svgLineChart(viewsSeries)}</div><div class="demographics"><div class="chart-card"><div class="chart-title">Top Follower Countries</div><div class="chart-note">Largest audience locations by follower count.</div>${barChart(countryData, 'No country demographic data returned.')}</div><div class="chart-card"><div class="chart-title">Top Follower Cities</div><div class="chart-note">Largest audience cities by follower count.</div>${barChart(cityData, 'No city demographic data returned.')}</div><div class="chart-card"><div class="chart-title">Follower Gender Distribution</div><div class="chart-note">Audience distribution returned by the Threads API.</div>${barChart(genderData, 'No gender demographic data returned.')}</div><div class="chart-card"><div class="chart-title">Report Notes</div><div class="chart-note">The report intentionally excludes post URLs, link URLs, permalinks and other URL-like fields. Values shown above are parsed from the returned Threads API series, including nested daily values and demographic breakdown results.</div></div></div></main><footer class="footer">Generated automatically for ${esc(accountName)} (${esc(username)}). This report contains graphical summaries only; raw API JSON and post URLs are not included.</footer></div></body></html>`;

const caption = `Threads Insights Report\n${accountName} (${username})\nPeriod: ${source.fromDate} to ${source.toDate}\nViews: ${formatNumber(viewsTotal)} | Likes: ${formatNumber(metricTotal('likes'))} | Replies: ${formatNumber(metricTotal('replies'))}`;
const fileName = `threads-insights-${source.fromDate}-to-${source.toDate}.html`;
return [{
  json: { ...source, reportTitle: `Threads Insights Report — ${accountName}`, telegramCaption: caption, reportFileName: fileName, reportGenerated: true, reportValidation: { viewsTotal, likes: metricTotal('likes'), replies: metricTotal('replies'), reposts: metricTotal('reposts'), quotes: metricTotal('quotes'), clicks: metricTotal('clicks'), followers, viewsPoints: viewsSeries.length, countryBars: countryData.length, cityBars: cityData.length, genderBars: genderData.length } },
  binary: { reportHtml: { data: Buffer.from(html, 'utf8').toString('base64'), mimeType: 'text/html', fileName } }
}];
